CREATE TABLE IF NOT EXISTS regions(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE COLLATE NOCASE);
CREATE TABLE IF NOT EXISTS roads(id INTEGER PRIMARY KEY,code TEXT NOT NULL UNIQUE COLLATE NOCASE,name TEXT NOT NULL,
 region_id INTEGER NOT NULL REFERENCES regions(id),length_m INTEGER NOT NULL CHECK(length_m>0),traffic INTEGER NOT NULL CHECK(traffic BETWEEN 1 AND 5),archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN(0,1)));
CREATE TABLE IF NOT EXISTS inspections(id INTEGER PRIMARY KEY,road_id INTEGER NOT NULL REFERENCES roads(id),inspected_on TEXT NOT NULL,
 condition TEXT NOT NULL CHECK(condition IN('Baik','Sedang','Rusak')),note TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE INDEX IF NOT EXISTS road_inspection ON inspections(road_id,inspected_on,id);
CREATE TABLE IF NOT EXISTS jobs(id INTEGER PRIMARY KEY,road_id INTEGER NOT NULL REFERENCES roads(id),name TEXT NOT NULL,
 starts_on TEXT NOT NULL,target_on TEXT NOT NULL,canceled INTEGER NOT NULL DEFAULT 0 CHECK(canceled IN(0,1)));
CREATE TABLE IF NOT EXISTS progress(id INTEGER PRIMARY KEY,job_id INTEGER NOT NULL REFERENCES jobs(id),recorded_on TEXT NOT NULL,
 percent INTEGER NOT NULL CHECK(percent BETWEEN 0 AND 100),note TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE INDEX IF NOT EXISTS job_progress ON progress(job_id,recorded_on,id);
